// Generated by scripts/build-toolkits.mjs. Do not edit; edit tools/*-toolkit and run npm run toolkits:build.
export const TOOLKIT_FILES: Record<'finance' | 'national', Record<string, string>> = {"finance":{"finance.cmd":"@echo off\r\nREM Tereflow Finance toolkit. Drag your filled workbook onto this file, or run:\r\nREM   finance.cmd check   FILE.xlsx\r\nREM   finance.cmd analyse FILE.xlsx\r\nREM   finance.cmd template\r\nsetlocal\r\ncd /d \"%~dp0\"\r\nwhere python >nul 2>nul\r\nif errorlevel 1 (\r\n  echo Python 3.9 or newer is needed. Install it from https://www.python.org/downloads/ and tick \"Add to PATH\".\r\n  pause & exit /b 1\r\n)\r\nif not exist .venv (\r\n  echo First run: setting up...\r\n  python -m venv .venv || (echo Could not create the environment & pause & exit /b 1)\r\n  .venv\\Scripts\\python -m pip install --quiet -r requirements.txt || (echo Install failed & pause & exit /b 1)\r\n)\r\nif \"%~1\"==\"\" (\r\n  echo Usage: finance.cmd check FILE.xlsx ^| analyse FILE.xlsx ^| template\r\n  pause & exit /b 1\r\n)\r\nset \"A=%~1\"\r\nif exist \"%~1\" if /i not \"%~1\"==\"check\" if /i not \"%~1\"==\"analyse\" if /i not \"%~1\"==\"template\" (\r\n  .venv\\Scripts\\python finance_tool.py check \"%~1\" && .venv\\Scripts\\python finance_tool.py analyse \"%~1\" --out \"%~dp1analysis\"\r\n  pause & exit /b 0\r\n)\r\n.venv\\Scripts\\python finance_tool.py %*\r\nif \"%~2\"==\"\" pause","finance_tool.py":"\"\"\"Tereflow Finance toolkit: check a bank-figures workbook and run the same analysis the website shows, on any PC.\r\n\r\n    python finance_tool.py template [--out tereflow-finance-template.xlsx]\r\n    python finance_tool.py check    FILE.xlsx|FILE.csv [--report problems.csv]\r\n    python finance_tool.py analyse  FILE.xlsx [--out analysis] [--country GHA]\r\n\r\n`check` validates every row against finance_config.json (allowed metrics, units, rate types, periods) and lists every\r\nproblem by row; it exits 0 only if the whole file is valid. `analyse` runs check first, then writes into the output folder:\r\n  scorecard.csv   who leads on each measure for the latest year\r\n  trends.csv      each bank's figures by year, with year-on-year change\r\n  rates.csv       deposit, savings and Treasury bill rates, and published fees\r\n  banks.csv       banks side by side, latest figure for each measure\r\n  report.md       the same plain-language insight the website gives\r\nThe Data sheet is read. If the workbook also has an Institutions sheet (institution_code, name, country_iso3, kind) it is used\r\nfor names and to tell banks from the central bank and sector totals; otherwise every institution is treated as a bank.\r\nNothing is estimated: a measure is only shown where the file holds the figures to calculate it.\r\n\"\"\"\r\nfrom __future__ import annotations\r\n\r\nimport argparse\r\nimport csv\r\nimport json\r\nimport re\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nHERE = Path(__file__).resolve().parent\r\nCFG = json.loads((HERE / \"finance_config.json\").read_text(encoding=\"utf-8\"))\r\nPERIOD = re.compile(r\"^\\d{4}(-(0[1-9]|1[0-2])|-Q[1-4])?$\")\r\nANNUAL = re.compile(r\"^\\d{4}$\")\r\n\r\n\r\ndef read_workbook(path: Path):\r\n    \"\"\"Returns (data rows as dicts, institutions as {code: {name, kind, country}}).\"\"\"\r\n    if path.suffix.lower() == \".csv\":\r\n        with path.open(newline=\"\", encoding=\"utf-8-sig\") as fh:\r\n            rows = [{(k or \"\").strip(): (v or \"\").strip() for k, v in r.items()} for r in csv.DictReader(fh)]\r\n        return rows, {}\r\n    from openpyxl import load_workbook\r\n    wb = load_workbook(path, read_only=True, data_only=True)\r\n    if \"Data\" not in wb.sheetnames:\r\n        raise SystemExit(\"The workbook has no sheet called Data\")\r\n    it = wb[\"Data\"].iter_rows(values_only=True)\r\n    head = [str(h).strip() if h is not None else \"\" for h in next(it, [])]\r\n    rows = [{h: (\"\" if v is None else str(v).strip()) for h, v in zip(head, r)} for r in it if r and any(v not in (None, \"\") for v in r)]\r\n    inst = {}\r\n    if \"Institutions\" in wb.sheetnames:\r\n        ii = wb[\"Institutions\"].iter_rows(values_only=True)\r\n        ih = [str(h).strip() if h is not None else \"\" for h in next(ii, [])]\r\n        for r in ii:\r\n            d = dict(zip(ih, r))\r\n            if d.get(\"institution_code\"):\r\n                inst[str(d[\"institution_code\"]).strip()] = {\"name\": d.get(\"name\") or d[\"institution_code\"], \"kind\": d.get(\"kind\") or \"bank\", \"country\": d.get(\"country_iso3\") or \"\"}\r\n    return rows, inst\r\n\r\n\r\ndef validate(rows):\r\n    problems = []\r\n    if rows:\r\n        missing = [c for c in CFG[\"columns\"] if c not in rows[0]]\r\n        if missing:\r\n            return [(1, \"header\", \"missing column(s): \" + \", \".join(missing))]\r\n    seen = set()\r\n    for i, r in enumerate(rows, start=2):\r\n        for c in CFG[\"required\"]:\r\n            if not r.get(c):\r\n                problems.append((i, c, \"required value is empty\"))\r\n        code, unit, iso, period, rt = r.get(\"metric_code\", \"\"), r.get(\"unit\", \"\"), r.get(\"country_iso3\", \"\"), r.get(\"period\", \"\"), r.get(\"rate_type\", \"\")\r\n        m = CFG[\"metrics\"].get(code)\r\n        if code and not m:\r\n            problems.append((i, \"metric_code\", f\"'{code}' is not an allowed metric\"))\r\n        if iso and not re.fullmatch(r\"[A-Z]{3}\", iso):\r\n            problems.append((i, \"country_iso3\", f\"'{iso}' must be three capital letters\"))\r\n        if period and not PERIOD.match(period):\r\n            problems.append((i, \"period\", f\"'{period}' is not a valid period (YYYY, YYYY-MM or YYYY-Qn)\"))\r\n        if r.get(\"value\", \"\"):\r\n            try:\r\n                float(r[\"value\"])\r\n            except ValueError:\r\n                problems.append((i, \"value\", f\"'{r['value']}' is not a number\"))\r\n        if m and unit and unit not in m[\"units\"]:\r\n            problems.append((i, \"unit\", f\"'{unit}' not allowed for {code}; use {', '.join(m['units'])}\"))\r\n        if m and unit == \"currency\" and not r.get(\"currency\"):\r\n            problems.append((i, \"currency\", \"currency code required when unit is currency\"))\r\n        if m and m[\"rate\"] and rt not in CFG[\"rate_types\"]:\r\n            problems.append((i, \"rate_type\", \"rate rows need rate_type, one of: \" + \", \".join(CFG[\"rate_types\"])))\r\n        if m and not m[\"rate\"] and rt:\r\n            problems.append((i, \"rate_type\", f\"{code} is not a rate, leave rate_type empty\"))\r\n        key = (r.get(\"institution_code\"), iso, period, code, rt)\r\n        if key in seen:\r\n            problems.append((i, \"row\", \"duplicate of an earlier row\"))\r\n        seen.add(key)\r\n    return problems\r\n\r\n\r\ndef bn(v):\r\n    return f\"{v / 1e9:.1f}bn\"\r\n\r\n\r\ndef analyse(rows, inst, country):\r\n    rows = [r for r in rows if r[\"country_iso3\"] == country]\r\n    kind = lambda c: inst.get(c, {}).get(\"kind\", \"bank\")\r\n    name = lambda c: inst.get(c, {}).get(\"name\", c)\r\n    label = lambda m: CFG[\"metrics\"][m][\"label\"]\r\n    codes = {r[\"institution_code\"] for r in rows}\r\n    banks = sorted((c for c in codes if kind(c) == \"bank\"), key=name)\r\n    sector = next((c for c in codes if kind(c) == \"sector\"), None)\r\n    central = next((c for c in codes if kind(c) == \"central_bank\"), None)\r\n\r\n    def val(c, m, per):\r\n        for r in rows:\r\n            if r[\"institution_code\"] == c and r[\"metric_code\"] == m and r[\"period\"] == per:\r\n                return float(r[\"value\"])\r\n        return None\r\n\r\n    def latest(c, m):\r\n        rr = sorted((r for r in rows if r[\"institution_code\"] == c and r[\"metric_code\"] == m), key=lambda r: r[\"period\"], reverse=True)\r\n        return (float(rr[0][\"value\"]), rr[0][\"period\"]) if rr else (None, None)\r\n\r\n    years = sorted({r[\"period\"] for r in rows if ANNUAL.match(r[\"period\"]) and r[\"metric_code\"] == \"TOTAL_ASSETS\" and r[\"institution_code\"] in banks})\r\n    yr = years[-1] if years else None\r\n    prior = str(int(yr) - 1) if yr else None\r\n\r\n    trends = []\r\n    for m in [\"TOTAL_ASSETS\", \"TOTAL_DEPOSITS\", \"TOTAL_LOANS\", \"CASH_BALANCE\", \"INVESTMENT_SECURITIES\", \"TOTAL_LIABILITIES\", \"TOTAL_EQUITY\", \"OPERATING_INCOME\", \"PROFIT_BEFORE_TAX\", \"PROFIT_AFTER_TAX\"]:\r\n        for b in banks:\r\n            pts = sorted((r for r in rows if r[\"institution_code\"] == b and r[\"metric_code\"] == m and ANNUAL.match(r[\"period\"])), key=lambda r: r[\"period\"])\r\n            for i, r in enumerate(pts):\r\n                ch = round((float(r[\"value\"]) / float(pts[i - 1][\"value\"]) - 1) * 100, 1) if i and float(pts[i - 1][\"value\"]) > 0 else \"\"\r\n                trends.append([label(m), name(b), r[\"period\"], float(r[\"value\"]), ch, r[\"source_note\"]])\r\n\r\n    score = []\r\n    if yr:\r\n        v = val\r\n        gp = lambda b, m: (v(b, m, yr) / v(b, m, prior) - 1) * 100 if v(b, m, yr) is not None and v(b, m, prior) else None\r\n        ratio = lambda b, a, z: (v(b, a, yr) / v(b, z, yr)) * 100 if v(b, a, yr) is not None and v(b, z, yr) else None\r\n        measures = [\r\n            (\"Deposits held\", \"higher\", lambda b: v(b, \"TOTAL_DEPOSITS\", yr), lambda x: bn(x)),\r\n            (\"Deposit growth\", \"higher\", lambda b: gp(b, \"TOTAL_DEPOSITS\"), lambda x: f\"{x:.0f}%\"),\r\n            (\"Cash on hand (share of assets)\", \"higher\", lambda b: ratio(b, \"CASH_BALANCE\", \"TOTAL_ASSETS\"), lambda x: f\"{x:.0f}%\"),\r\n            (\"Profit growth\", \"higher\", lambda b: gp(b, \"PROFIT_AFTER_TAX\"), lambda x: f\"{x:.0f}%\"),\r\n            (\"Profit on each unit of income\", \"higher\", lambda b: ratio(b, \"PROFIT_BEFORE_TAX\", \"OPERATING_INCOME\"), lambda x: f\"{x:.0f}%\"),\r\n            (\"Own money behind the balance sheet\", \"higher\", lambda b: ratio(b, \"TOTAL_EQUITY\", \"TOTAL_ASSETS\"), lambda x: f\"{x:.1f}%\"),\r\n            (\"Capital adequacy\", \"higher\", lambda b: v(b, \"CAPITAL_ADEQUACY\", yr), lambda x: f\"{x:.2f}%\"),\r\n            (\"Loan quality (lower is better)\", \"lower\", lambda b: v(b, \"NPL_RATIO\", yr), lambda x: f\"{x:.2f}%\"),\r\n            (\"Interest paid on deposits\", \"higher\", lambda b: v(b, \"DEPOSIT_RATE_AVG\", yr), lambda x: f\"{x:.2f}%\"),\r\n        ]\r\n        for title, better, f, fmt in measures:\r\n            vals = [(b, f(b)) for b in banks if f(b) is not None]\r\n            if len(vals) < 2:\r\n                continue\r\n            vals.sort(key=lambda t: t[1], reverse=(better == \"higher\"))\r\n            score.append([title, yr] + [x for b, x_ in vals for x in (name(b), fmt(x_))])\r\n\r\n    rates = []\r\n    for r in rows:\r\n        if CFG[\"metrics\"][r[\"metric_code\"]][\"rate\"]:\r\n            rates.append([name(r[\"institution_code\"]), label(r[\"metric_code\"]), r[\"period\"], float(r[\"value\"]), r.get(\"rate_type\", \"\"), r[\"source_note\"]])\r\n    rates.sort(key=lambda x: (x[0], x[1], x[2]))\r\n\r\n    table = []\r\n    for m in [\"TOTAL_ASSETS\", \"CASH_BALANCE\", \"INVESTMENT_SECURITIES\", \"TOTAL_LOANS\", \"TOTAL_DEPOSITS\", \"TOTAL_LIABILITIES\", \"TOTAL_EQUITY\", \"OPERATING_INCOME\", \"PROFIT_BEFORE_TAX\", \"PROFIT_AFTER_TAX\", \"CAPITAL_ADEQUACY\", \"NPL_RATIO\", \"RETURN_ON_EQUITY\", \"COST_TO_INCOME\", \"BRANCH_COUNT\", \"DEPOSIT_RATE_AVG\"]:\r\n        cells = []\r\n        for b in banks:\r\n            x, p = latest(b, m)\r\n            cells.append(\"not held\" if x is None else f\"{x:,.2f}\".rstrip(\"0\").rstrip(\".\") + f\" ({p})\")\r\n        if any(c != \"not held\" for c in cells):\r\n            table.append([label(m)] + cells)\r\n\r\n    L = [f\"# Bank intelligence: {country}\", \"\", f\"Latest annual year compared: {yr or 'none'}. Every figure comes from the file you supplied; nothing is estimated.\", \"\"]\r\n    if score:\r\n        L += [\"## Who is doing well\", \"\"]\r\n        tally = {}\r\n        for row in score:\r\n            tally.setdefault(row[2], []).append(row[0].split(\" (\")[0].lower())\r\n        L.append(\"; \".join(f\"{b} leads on {len(ms)} ({', '.join(ms)})\" for b, ms in sorted(tally.items(), key=lambda t: -len(t[1]))) + \". No bank leads on everything, so the right choice depends on what you need.\")\r\n        L.append(\"\")\r\n        for row in score:\r\n            L.append(f\"- **{row[0]}**: \" + \" | \".join(f\"{row[i]} {row[i + 1]}\" for i in range(2, len(row), 2)))\r\n        L.append(\"\")\r\n    if yr and banks:\r\n        big = max(banks, key=lambda b: val(b, \"TOTAL_ASSETS\", yr) or 0)\r\n        if val(big, \"TOTAL_ASSETS\", yr):\r\n            sec = (val(sector, \"TOTAL_ASSETS\", yr) or val(sector, \"TOTAL_ASSETS\", yr + \"-12\")) if sector else None\r\n            L += [\"## Size\", \"\", f\"{name(big)} holds the most assets of the banks listed, at {bn(val(big, 'TOTAL_ASSETS', yr))}\" + (f\", about {val(big, 'TOTAL_ASSETS', yr) / sec * 100:.0f}% of the whole banking sector.\" if sec else \".\"), \"\"]\r\n    if central:\r\n        pol, pp = latest(central, \"POLICY_RATE\")\r\n        if pol is not None:\r\n            L += [\"## Cost of borrowing and saving\", \"\", f\"Central bank policy rate: {pol}% ({pp}).\"]\r\n            for m in (\"TBILL_91D\", \"TBILL_364D\"):\r\n                x, p = latest(central, m)\r\n                if x is not None:\r\n                    L.append(f\"{label(m)}: {x}% ({p}).\")\r\n            if sector:\r\n                for m in (\"LENDING_RATE\", \"REFERENCE_RATE\", \"SAVINGS_RATE\", \"DEPOSIT_RATE\"):\r\n                    if m in CFG[\"metrics\"]:\r\n                        x, p = latest(sector, m)\r\n                        if x is not None:\r\n                            L.append(f\"Sector average, {label(m).lower()}: {x}% ({p}).\")\r\n            L.append(\"\")\r\n    L += [\"## Where every figure comes from\", \"\", \"Each row of trends.csv, rates.csv and banks.csv carries its source note from your file.\", \"\"]\r\n    return {\"scorecard\": score, \"trends\": trends, \"rates\": rates, \"banks\": [[\"Figure\"] + [name(b) for b in banks]] + table, \"report\": \"\\n\".join(L)}\r\n\r\n\r\ndef write_csv(path, header, rows):\r\n    with path.open(\"w\", newline=\"\", encoding=\"utf-8-sig\") as fh:\r\n        w = csv.writer(fh)\r\n        if header:\r\n            w.writerow(header)\r\n        w.writerows(rows)\r\n\r\n\r\ndef cmd_template(out):\r\n    from openpyxl import Workbook\r\n    wb = Workbook()\r\n    ws = wb.active\r\n    ws.title = \"Data\"\r\n    ws.append(CFG[\"columns\"])\r\n    ms = wb.create_sheet(\"Metrics\")\r\n    ms.append([\"metric_code\", \"label\", \"allowed units\", \"is a rate (needs rate_type)\", \"ranking\"])\r\n    for code, m in CFG[\"metrics\"].items():\r\n        ms.append([code, m[\"label\"], \", \".join(m[\"units\"]), \"yes\" if m[\"rate\"] else \"no\", {\"higher\": \"higher ranks first\", \"lower\": \"lower ranks first\"}.get(m.get(\"better\"), \"not ranked\")])\r\n    ins = wb.create_sheet(\"Institutions\")\r\n    ins.append([\"institution_code\", \"name\", \"country_iso3\", \"kind\"])\r\n    ins.append([\"EXAMPLE_BANK\", \"Example Bank\", \"GHA\", \"bank\"])\r\n    ins.append([\"EXAMPLE_CENTRAL_BANK\", \"Example Central Bank\", \"GHA\", \"central_bank\"])\r\n    ins.append([\"EXAMPLE_SECTOR\", \"Banking sector (aggregate)\", \"GHA\", \"sector\"])\r\n    ex = wb.create_sheet(\"Example\")\r\n    ex.append(CFG[\"columns\"])\r\n    ex.append([\"EXAMPLE_BANK\", \"GHA\", \"2025\", \"TOTAL_ASSETS\", 31529847000, \"currency\", \"GHS\", \"EXAMPLE ONLY: annual report 2025, statement of financial position\", \"\"])\r\n    ex.append([\"EXAMPLE_BANK\", \"GHA\", \"2025\", \"NPL_RATIO\", 17, \"percent\", \"\", \"EXAMPLE ONLY: annual report 2025\", \"\"])\r\n    wb.save(out)\r\n    print(\"wrote\", out)\r\n\r\n\r\ndef cmd_check(path, report=None):\r\n    rows, _ = read_workbook(path)\r\n    problems = validate(rows)\r\n    print(f\"{path.name}: {len(rows)} data row(s), {len(problems)} problem(s)\")\r\n    for r, c, m in problems[:200]:\r\n        print(f\"  row {r} [{c}]: {m}\")\r\n    if report:\r\n        write_csv(Path(report), [\"row\", \"column\", \"problem\"], problems)\r\n    print(\"VALID\" if rows and not problems else \"NOT VALID\")\r\n    return 0 if rows and not problems else 1\r\n\r\n\r\ndef cmd_analyse(path, out, country):\r\n    rows, inst = read_workbook(path)\r\n    problems = validate(rows)\r\n    if problems or not rows:\r\n        print(f\"The file has {len(problems)} problem(s); fix them first (run: finance_tool.py check {path.name})\")\r\n        for r, c, m in problems[:20]:\r\n            print(f\"  row {r} [{c}]: {m}\")\r\n        return 1\r\n    out.mkdir(parents=True, exist_ok=True)\r\n    for c in [country] if country else sorted({r[\"country_iso3\"] for r in rows}):\r\n        res = analyse(rows, inst, c)\r\n        d = out / c\r\n        d.mkdir(parents=True, exist_ok=True)\r\n        n = max((len(x) for x in res[\"scorecard\"]), default=2)\r\n        write_csv(d / \"scorecard.csv\", [\"measure\", \"year\"] + sum([[f\"rank{i}_bank\", f\"rank{i}_value\"] for i in range(1, (n - 2) // 2 + 1)], []), res[\"scorecard\"])\r\n        write_csv(d / \"trends.csv\", [\"measure\", \"bank\", \"year\", \"value\", \"change_vs_previous_year_pct\", \"source_note\"], res[\"trends\"])\r\n        write_csv(d / \"rates.csv\", [\"institution\", \"rate\", \"period\", \"value_pct\", \"rate_type\", \"source_note\"], res[\"rates\"])\r\n        write_csv(d / \"banks.csv\", None, res[\"banks\"])\r\n        (d / \"report.md\").write_text(res[\"report\"], encoding=\"utf-8\")\r\n        print(f\"{c}: wrote scorecard, trends, rates, banks and report to {d}\")\r\n    return 0\r\n\r\n\r\ndef main(argv=None):\r\n    p = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\r\n    sub = p.add_subparsers(dest=\"cmd\", required=True)\r\n    t = sub.add_parser(\"template\"); t.add_argument(\"--out\", default=\"tereflow-finance-template.xlsx\")\r\n    c = sub.add_parser(\"check\"); c.add_argument(\"file\"); c.add_argument(\"--report\")\r\n    a = sub.add_parser(\"analyse\"); a.add_argument(\"file\"); a.add_argument(\"--out\", default=\"analysis\"); a.add_argument(\"--country\")\r\n    x = p.parse_args(argv)\r\n    if x.cmd == \"template\":\r\n        cmd_template(Path(x.out))\r\n        return 0\r\n    if x.cmd == \"check\":\r\n        return cmd_check(Path(x.file), x.report)\r\n    return cmd_analyse(Path(x.file), Path(x.out), x.country.upper() if x.country else None)\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    sys.exit(main())\r\n","finance_config.json":"{\n  \"_about\": \"Allowed values for the bank Excel template. Edit this file, then run: python scripts/finance/bank_load.py seed-defs. 'better' says whether a higher or lower value ranks first (used for institution rankings).\",\n  \"columns\": [\n    \"institution_code\",\n    \"country_iso3\",\n    \"period\",\n    \"metric_code\",\n    \"value\",\n    \"unit\",\n    \"currency\",\n    \"source_note\",\n    \"rate_type\"\n  ],\n  \"required\": [\n    \"institution_code\",\n    \"country_iso3\",\n    \"period\",\n    \"metric_code\",\n    \"value\",\n    \"unit\",\n    \"source_note\"\n  ],\n  \"metrics\": {\n    \"TOTAL_ASSETS\": {\n      \"label\": \"Total assets\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"TOTAL_LOANS\": {\n      \"label\": \"Total loans\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"TOTAL_DEPOSITS\": {\n      \"label\": \"Total deposits\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"NPL_RATIO\": {\n      \"label\": \"Non-performing loans ratio\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": false,\n      \"better\": \"lower\"\n    },\n    \"CAPITAL_ADEQUACY\": {\n      \"label\": \"Capital adequacy ratio\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"RETURN_ON_ASSETS\": {\n      \"label\": \"Return on assets\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"BRANCH_COUNT\": {\n      \"label\": \"Branches\",\n      \"units\": [\n        \"count\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"LENDING_RATE\": {\n      \"label\": \"Lending rate\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"DEPOSIT_RATE\": {\n      \"label\": \"Deposit rate\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"TRADE_FINANCE_FEE\": {\n      \"label\": \"Trade finance fee\",\n      \"units\": [\n        \"percent\",\n        \"currency\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"PROFIT_AFTER_TAX\": {\n      \"label\": \"Profit after tax\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"RETURN_ON_EQUITY\": {\n      \"label\": \"Return on equity\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": false,\n      \"better\": \"higher\"\n    },\n    \"COST_TO_INCOME\": {\n      \"label\": \"Cost to income ratio\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": false,\n      \"better\": \"lower\"\n    },\n    \"POLICY_RATE\": {\n      \"label\": \"Central bank policy rate\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"none\"\n    },\n    \"REFERENCE_RATE\": {\n      \"label\": \"Reference (base) rate for loan pricing\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"FEE_LC_IMPORT_SIGHT\": {\n      \"label\": \"Import letter of credit, sight: establishment fee (per quarter)\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"FEE_LC_IMPORT_USANCE\": {\n      \"label\": \"Import letter of credit, usance: establishment fee (per quarter)\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"FEE_LC_EXPORT_NEGOTIATION\": {\n      \"label\": \"Export letter of credit: negotiation fee\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"FEE_GUARANTEE_PERIODIC\": {\n      \"label\": \"Guarantee or bond: periodic charge (per quarter)\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"FEE_COLLECTION_EXPORT\": {\n      \"label\": \"Export bill for collection: handling commission\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"lower\"\n    },\n    \"CASH_BALANCE\": {\n      \"label\": \"Cash and cash equivalents\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"none\"\n    },\n    \"INVESTMENT_SECURITIES\": {\n      \"label\": \"Investment securities held\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"none\"\n    },\n    \"TOTAL_EQUITY\": {\n      \"label\": \"Total equity (shareholders' funds)\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"none\"\n    },\n    \"TOTAL_LIABILITIES\": {\n      \"label\": \"Total liabilities\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"none\"\n    },\n    \"OPERATING_INCOME\": {\n      \"label\": \"Operating income\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"none\"\n    },\n    \"PROFIT_BEFORE_TAX\": {\n      \"label\": \"Profit before tax\",\n      \"units\": [\n        \"currency\"\n      ],\n      \"rate\": false,\n      \"better\": \"none\"\n    },\n    \"DEPOSIT_RATE_AVG\": {\n      \"label\": \"Average interest rate paid on customer deposits\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"SAVINGS_RATE\": {\n      \"label\": \"Savings account interest rate (standard account, 'up to')\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"TERM_SAVINGS_RATE\": {\n      \"label\": \"Fixed-term goal savings interest rate ('up to')\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"DEMAND_DEPOSIT_RATE\": {\n      \"label\": \"Demand deposit rate\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"TIME_DEPOSIT_RATE_3M\": {\n      \"label\": \"Time deposit rate, 3 months\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"TIME_DEPOSIT_RATE_6M\": {\n      \"label\": \"Time deposit rate, 6 months\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"higher\"\n    },\n    \"TBILL_91D\": {\n      \"label\": \"Treasury bill yield, 91 days (investment)\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"none\"\n    },\n    \"TBILL_182D\": {\n      \"label\": \"Treasury bill yield, 182 days (investment)\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"none\"\n    },\n    \"TBILL_364D\": {\n      \"label\": \"Treasury bill yield, 364 days (investment)\",\n      \"units\": [\n        \"percent\"\n      ],\n      \"rate\": true,\n      \"better\": \"none\"\n    }\n  },\n  \"rate_types\": [\n    \"fixed\",\n    \"variable\",\n    \"indicative\",\n    \"policy\"\n  ],\n  \"period_format\": \"YYYY, YYYY-MM or YYYY-Qn (for example 2025, 2025-06, 2025-Q2)\"\n}\n","requirements.txt":"openpyxl>=3.1\r\n","README.txt":"TEREFLOW FINANCE TOOLKIT\r\n========================\r\nChecks a bank-figures workbook against exactly what Tereflow accepts, and runs the same analysis the website\r\nshows (scorecard, multi-year trends, deposit and investment rates). It works offline, needs no login and holds no secrets.\r\n\r\nYou need: Windows, Python 3.9 or newer (python.org, tick \"Add to PATH\"). The first run sets itself up.\r\n\r\n1. Get a blank template:      finance.cmd template\r\n   Fill the Data sheet (one row per institution, country, period, metric). The Metrics sheet lists every allowed\r\n   metric and unit. The Institutions sheet is optional but gives names and tells banks from the central bank\r\n   (kind: bank, central_bank, sector).\r\n2. Check it:                  finance.cmd check MYFILE.xlsx\r\n   Every problem is listed by row. Nothing is accepted until the whole file is valid.\r\n3. Analyse it:                finance.cmd analyse MYFILE.xlsx\r\n   Or drag MYFILE.xlsx onto finance.cmd. Results go to an \"analysis\" folder: scorecard.csv, trends.csv, rates.csv,\r\n   banks.csv and report.md. Open the csv files in Excel.\r\n\r\nRules the checker enforces: metric_code must be in the Metrics sheet; unit must be allowed for that metric; rate\r\nrows need rate_type (fixed, variable, indicative, policy); period is YYYY, YYYY-MM or YYYY-Qn; every row needs a\r\nsource_note saying where the figure was published; no duplicate rows. Money is in whole currency units (GHS 31,529,847,000,\r\nnot thousands). Nothing is estimated: a measure only appears when the file holds the figures to calculate it.\r\n\r\nTo put the data on the website, an admin uploads the same file in Admin > Finance. This toolkit is for preparing\r\nand checking it anywhere first. The file finance_config.json is the rule set; replace it with a newer copy from the\r\nadmin download when the metric list changes."},"national":{"national.cmd":"@echo off\r\nREM Tereflow National toolkit. Drag your filled workbook onto this file, or run:\r\nREM   national.cmd check   FILE.xlsx\r\nREM   national.cmd analyse FILE.xlsx\r\nREM   national.cmd template\r\nsetlocal\r\ncd /d \"%~dp0\"\r\nwhere python >nul 2>nul\r\nif errorlevel 1 (\r\n  echo Python 3.9 or newer is needed. Install it from https://www.python.org/downloads/ and tick \"Add to PATH\".\r\n  pause & exit /b 1\r\n)\r\nif not exist .venv (\r\n  echo First run: setting up...\r\n  python -m venv .venv || (echo Could not create the environment & pause & exit /b 1)\r\n  .venv\\Scripts\\python -m pip install --quiet -r requirements.txt || (echo Install failed & pause & exit /b 1)\r\n)\r\nif \"%~1\"==\"\" (\r\n  echo Usage: national.cmd check FILE.xlsx --frequency monthly ^| analyse FILE.xlsx --frequency monthly ^| template\r\n  pause & exit /b 1\r\n)\r\nset \"A=%~1\"\r\nif exist \"%~1\" if /i not \"%~1\"==\"check\" if /i not \"%~1\"==\"analyse\" if /i not \"%~1\"==\"template\" (\r\n  echo Drag-and-drop needs the frequency. Run: national.cmd analyse \"%~1\" --frequency monthly\r\n  pause & exit /b 0\r\n)\r\n.venv\\Scripts\\python national_tool.py %*\r\nif \"%~2\"==\"\" pause","national_tool.py":"\"\"\"Tereflow National statistics toolkit: check a trade-series workbook and analyse it, on any PC.\r\n\r\n    python national_tool.py template [--out tereflow-national-template.xlsx]\r\n    python national_tool.py check    FILE.xlsx|FILE.csv --frequency monthly|quarterly|annual [--report problems.csv]\r\n    python national_tool.py analyse  FILE.xlsx --frequency monthly|quarterly|annual [--out analysis]\r\n\r\nanalyse writes, per country and flow:\r\n  totals.csv    the total for each period, change on the same period a year earlier, and the year-to-date growth\r\n  products.csv  each product (HS code) latest period against the same period a year earlier, biggest movers first\r\n  report.md     a plain-language summary\r\nOnly figures in the file are used. A change is shown only when the same period a year earlier is in the file.\r\n\"\"\"\r\nfrom __future__ import annotations\r\n\r\nimport argparse\r\nimport csv\r\nimport json\r\nimport re\r\nimport sys\r\nfrom collections import defaultdict\r\nfrom pathlib import Path\r\n\r\nHERE = Path(__file__).resolve().parent\r\nCFG = json.loads((HERE / \"national_config.json\").read_text(encoding=\"utf-8\"))\r\nPERIODS = {\"monthly\": re.compile(r\"^\\d{4}-(0[1-9]|1[0-2])$\"), \"quarterly\": re.compile(r\"^\\d{4}-Q[1-4]$\"), \"annual\": re.compile(r\"^\\d{4}$\")}\r\nHS = re.compile(r\"^(TOTAL|\\d{2}|\\d{4}|\\d{6})$\")\r\n\r\n\r\ndef read(path: Path):\r\n    if path.suffix.lower() == \".csv\":\r\n        with path.open(newline=\"\", encoding=\"utf-8-sig\") as fh:\r\n            return [{(k or \"\").strip(): (v or \"\").strip() for k, v in r.items()} for r in csv.DictReader(fh)]\r\n    from openpyxl import load_workbook\r\n    wb = load_workbook(path, read_only=True, data_only=True)\r\n    ws = wb[\"Data\"] if \"Data\" in wb.sheetnames else wb.worksheets[0]\r\n    it = ws.iter_rows(values_only=True)\r\n    head = [str(h).strip() if h is not None else \"\" for h in next(it, [])]\r\n    return [{h: (\"\" if v is None else str(v).strip()) for h, v in zip(head, r)} for r in it if r and any(v not in (None, \"\") for v in r)]\r\n\r\n\r\ndef validate(rows, freq):\r\n    problems = []\r\n    if rows:\r\n        miss = [c for c in CFG[\"columns\"] if c not in rows[0]]\r\n        if miss:\r\n            return [(1, \"header\", \"missing column(s): \" + \", \".join(miss))]\r\n    seen = set()\r\n    for i, r in enumerate(rows, start=2):\r\n        for c in CFG[\"required\"]:\r\n            if not r.get(c):\r\n                problems.append((i, c, \"required value is empty\"))\r\n        if r.get(\"country_iso3\") and not re.fullmatch(r\"[A-Z]{3}\", r[\"country_iso3\"]):\r\n            problems.append((i, \"country_iso3\", \"must be three capital letters\"))\r\n        if r.get(\"flow\") and r[\"flow\"] not in CFG[\"flows\"]:\r\n            problems.append((i, \"flow\", \"must be X (exports) or M (imports)\"))\r\n        if r.get(\"period\") and not PERIODS[freq].match(r[\"period\"]):\r\n            problems.append((i, \"period\", f\"'{r['period']}' does not match {freq}: {CFG['period_formats'][freq]}\"))\r\n        if r.get(\"hs_code\") and not HS.match(r[\"hs_code\"]):\r\n            problems.append((i, \"hs_code\", \"must be TOTAL or a 2, 4 or 6 digit HS code (keep leading zeros)\"))\r\n        if r.get(\"value_usd\"):\r\n            try:\r\n                if float(r[\"value_usd\"]) < 0:\r\n                    problems.append((i, \"value_usd\", \"must not be negative\"))\r\n            except ValueError:\r\n                problems.append((i, \"value_usd\", f\"'{r['value_usd']}' is not a number\"))\r\n        k = (r.get(\"country_iso3\"), r.get(\"flow\"), r.get(\"period\"), r.get(\"hs_code\"))\r\n        if k in seen:\r\n            problems.append((i, \"row\", \"duplicate of an earlier row\"))\r\n        seen.add(k)\r\n    return problems\r\n\r\n\r\ndef prev_year(p):\r\n    return f\"{int(p[:4]) - 1}{p[4:]}\"\r\n\r\n\r\ndef pct(a, b):\r\n    return round((a / b - 1) * 100, 1) if b else None\r\n\r\n\r\ndef write_csv(path, header, rows):\r\n    with path.open(\"w\", newline=\"\", encoding=\"utf-8-sig\") as fh:\r\n        w = csv.writer(fh)\r\n        w.writerow(header)\r\n        w.writerows(rows)\r\n\r\n\r\ndef usd(v):\r\n    return f\"USD {v / 1e9:.2f}bn\" if v >= 1e9 else f\"USD {v / 1e6:.1f}m\"\r\n\r\n\r\ndef cmd_analyse(path, freq, out):\r\n    rows = read(path)\r\n    problems = validate(rows, freq)\r\n    if problems or not rows:\r\n        print(f\"The file has {len(problems)} problem(s); fix them first (run: national_tool.py check ...)\")\r\n        for r, c, m in problems[:20]:\r\n            print(f\"  row {r} [{c}]: {m}\")\r\n        return 1\r\n    data = defaultdict(dict)\r\n    for r in rows:\r\n        data[(r[\"country_iso3\"], r[\"flow\"], r[\"hs_code\"])][r[\"period\"]] = float(r[\"value_usd\"])\r\n    out.mkdir(parents=True, exist_ok=True)\r\n    for iso, flow in sorted({(k[0], k[1]) for k in data}):\r\n        d = out / f\"{iso}_{flow}\"\r\n        d.mkdir(parents=True, exist_ok=True)\r\n        tot = data.get((iso, flow, \"TOTAL\"), {})\r\n        trows = []\r\n        for p in sorted(tot):\r\n            py = tot.get(prev_year(p))\r\n            trows.append([p, tot[p], \"\" if py is None else pct(tot[p], py)])\r\n        write_csv(d / \"totals.csv\", [\"period\", \"value_usd\", \"change_vs_same_period_last_year_pct\"], trows)\r\n        lines = [f\"# {iso} {CFG['flows'][flow]}\", \"\"]\r\n        if tot:\r\n            last = max(tot)\r\n            py = tot.get(prev_year(last))\r\n            lines.append(f\"Latest period in the file: {last}, {usd(tot[last])}\" + (f\", {pct(tot[last], py):+.1f}% on {prev_year(last)}.\" if py else \", with no figure a year earlier to compare.\"))\r\n            if freq == \"monthly\":\r\n                yr = last[:4]\r\n                ytd = sum(v for p, v in tot.items() if p[:4] == yr)\r\n                ytd_py = sum(tot[prev_year(p)] for p in tot if p[:4] == yr and prev_year(p) in tot)\r\n                n = sum(1 for p in tot if p[:4] == yr and prev_year(p) in tot)\r\n                if n and n == sum(1 for p in tot if p[:4] == yr):\r\n                    lines.append(f\"Year to date {yr}: {usd(ytd)}, {pct(ytd, ytd_py):+.1f}% on the same months of {int(yr) - 1}.\")\r\n        prod = []\r\n        for (c, f, hs), series in data.items():\r\n            if c != iso or f != flow or hs == \"TOTAL\" or not series:\r\n                continue\r\n            last = max(series)\r\n            py = series.get(prev_year(last))\r\n            prod.append([hs, last, series[last], \"\" if py is None else py, \"\" if py is None else pct(series[last], py), \"\" if py is None else series[last] - py])\r\n        prod.sort(key=lambda x: -abs(x[5]) if x[5] != \"\" else 0)\r\n        write_csv(d / \"products.csv\", [\"hs_code\", \"latest_period\", \"value_usd\", \"same_period_last_year_usd\", \"change_pct\", \"change_usd\"], prod)\r\n        movers = [x for x in prod if x[5] != \"\"][:5]\r\n        if movers:\r\n            lines += [\"\", \"Biggest movers (value change on the same period a year earlier):\"]\r\n            lines += [f\"- HS {x[0]} ({x[1]}): {usd(x[2])}, {x[4]:+.1f}%\" for x in movers]\r\n        (d / \"report.md\").write_text(\"\\n\".join(lines) + \"\\n\", encoding=\"utf-8\")\r\n        print(f\"{iso} {flow}: wrote totals, products and report to {d}\")\r\n    return 0\r\n\r\n\r\ndef cmd_check(path, freq, report):\r\n    rows = read(path)\r\n    problems = validate(rows, freq)\r\n    print(f\"{path.name}: {len(rows)} data row(s), {len(problems)} problem(s)\")\r\n    for r, c, m in problems[:200]:\r\n        print(f\"  row {r} [{c}]: {m}\")\r\n    if report:\r\n        write_csv(Path(report), [\"row\", \"column\", \"problem\"], problems)\r\n    print(\"VALID\" if rows and not problems else \"NOT VALID\")\r\n    return 0 if rows and not problems else 1\r\n\r\n\r\ndef cmd_template(out):\r\n    from openpyxl import Workbook\r\n    wb = Workbook()\r\n    ws = wb.active\r\n    ws.title = \"Data\"\r\n    ws.append(CFG[\"columns\"])\r\n    ex = wb.create_sheet(\"How to fill\")\r\n    for line in [\"One row per country, flow, period and product.\", \"flow: X = exports, M = imports.\", \"period: \" + \"; \".join(f\"{k}: {v}\" for k, v in CFG[\"period_formats\"].items()), \"hs_code: \" + CFG[\"hs_code\"], \"value_usd: whole US dollars, numbers only.\", \"source_note: where the figure was published (table, page or release name).\"]:\r\n        ex.append([line])\r\n    wb.save(out)\r\n    print(\"wrote\", out)\r\n\r\n\r\ndef main(argv=None):\r\n    p = argparse.ArgumentParser(description=__doc__.split(\"\\n\")[0])\r\n    sub = p.add_subparsers(dest=\"cmd\", required=True)\r\n    t = sub.add_parser(\"template\"); t.add_argument(\"--out\", default=\"tereflow-national-template.xlsx\")\r\n    for n in (\"check\", \"analyse\"):\r\n        s = sub.add_parser(n); s.add_argument(\"file\"); s.add_argument(\"--frequency\", required=True, choices=list(PERIODS))\r\n        if n == \"check\":\r\n            s.add_argument(\"--report\")\r\n        else:\r\n            s.add_argument(\"--out\", default=\"analysis\")\r\n    x = p.parse_args(argv)\r\n    if x.cmd == \"template\":\r\n        cmd_template(Path(x.out))\r\n        return 0\r\n    if x.cmd == \"check\":\r\n        return cmd_check(Path(x.file), x.frequency, x.report)\r\n    return cmd_analyse(Path(x.file), x.frequency, Path(x.out))\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    sys.exit(main())\r\n","national_config.json":"{\n  \"_about\": \"Template for national statistics series (monthly or quarterly trade values from a country's own statistics office). Edit this file to change allowed values; no code change is needed.\",\n  \"columns\": [\"country_iso3\", \"flow\", \"period\", \"hs_code\", \"value_usd\", \"source_note\"],\n  \"required\": [\"country_iso3\", \"flow\", \"period\", \"hs_code\", \"value_usd\", \"source_note\"],\n  \"flows\": {\"X\": \"exports\", \"M\": \"imports\"},\n  \"frequencies\": [\"monthly\", \"quarterly\", \"annual\"],\n  \"period_formats\": {\"monthly\": \"YYYY-MM, for example 2026-03\", \"quarterly\": \"YYYY-Qn, for example 2026-Q1\", \"annual\": \"YYYY, for example 2025\"},\n  \"hs_code\": \"TOTAL for the country's overall total, or a 2, 4 or 6 digit HS code\",\n  \"priority_countries\": [\"CIV\", \"GHA\", \"NGA\", \"KEN\", \"NLD\", \"GBR\", \"ARE\", \"IND\", \"CHN\"]\n}","requirements.txt":"openpyxl>=3.1\r\n","README.txt":"TEREFLOW NATIONAL STATISTICS TOOLKIT\r\n====================================\r\nChecks a trade-series workbook (monthly, quarterly or annual figures from a country's own statistics office) against\r\nexactly what Tereflow accepts, and analyses it: totals by period, change on the same period a year earlier, year to date,\r\nand the biggest-moving products. Works offline, no login, no secrets.\r\n\r\nYou need: Windows, Python 3.9 or newer (python.org, tick \"Add to PATH\"). The first run sets itself up.\r\n\r\n1. Blank template:           national.cmd template\r\n2. Check:                    national.cmd check MYFILE.xlsx --frequency monthly\r\n3. Analyse:                  national.cmd analyse MYFILE.xlsx --frequency monthly\r\n   Results go to an \"analysis\" folder, one sub-folder per country and flow: totals.csv, products.csv, report.md.\r\n\r\nColumns: country_iso3, flow (X exports, M imports), period (monthly 2026-03, quarterly 2026-Q1, annual 2025), hs_code\r\n(TOTAL, or 2, 4 or 6 digits, keep leading zeros), value_usd (whole US dollars), source_note (where it was published).\r\nA change is shown only if the same period a year earlier is in the file. To load the data on the website an admin\r\nuploads the same file in Admin > National data, after registering the source and its frequency."}};
